(function(global, factory) {
  typeof exports === 'object' && typeof module !== 'undefined' ? factory(exports) :
  typeof define === 'function' && define.amd ? define(['exports'], factory) :
  (global = typeof globalThis !== 'undefined' ? globalThis : global || self, factory(global.Mp4Muxer = {}));
})(this, (function(exports) { 'use strict';

  class ArrayBufferTarget {
    constructor() { this.buffer = null; }
  }

  class StreamWriter {
    constructor() {
      this.chunks = [];
      this.totalLength = 0;
    }
    write(bytes) {
      this.chunks.push(bytes);
      this.totalLength += bytes.length;
    }
    finalize() {
      const result = new Uint8Array(this.totalLength);
      let offset = 0;
      for (const chunk of this.chunks) {
        result.set(chunk, offset);
        offset += chunk.length;
      }
      return result.buffer;
    }
  }

  function box(type, ...children) {
    let size = 8;
    const bufs = [];
    for (const c of children) {
      if (!c) continue;
      if (typeof c === 'string') {
        const b = new TextEncoder().encode(c);
        bufs.push(b);
        size += b.length;
      } else if (c instanceof Uint8Array) {
        bufs.push(c);
        size += c.length;
      } else if (c instanceof ArrayBuffer) {
        const b = new Uint8Array(c);
        bufs.push(b);
        size += b.length;
      }
    }
    const header = new Uint8Array(8);
    new DataView(header.buffer).setUint32(0, size);
    header.set(new TextEncoder().encode(type), 4);
    const full = new Uint8Array(size);
    full.set(header, 0);
    let off = 8;
    for (const b of bufs) {
      full.set(b, off);
      off += b.length;
    }
    return full;
  }

  function u32(val) {
    const b = new Uint8Array(4);
    new DataView(b.buffer).setUint32(0, Math.floor(val));
    return b;
  }
  function u16(val) {
    const b = new Uint8Array(2);
    new DataView(b.buffer).setUint16(0, Math.floor(val));
    return b;
  }

  class Muxer {
    constructor(options) {
      this.options = options;
      this.target = options.target;
      this.writer = new StreamWriter();
      this.videoChunks = [];
      this.audioChunks = [];
      this.videoDesc = null;
      this.audioDesc = null;

      const ftyp = box('ftyp', 'isom', u32(0x200), 'isom', 'iso2', 'avc1', 'mp41');
      this.writer.write(ftyp);
    }

    addVideoChunk(chunk, meta) {
      const data = new Uint8Array(chunk.byteLength);
      chunk.copyTo(data);
      this.videoChunks.push({
        data,
        timestamp: chunk.timestamp,
        duration: chunk.duration || 33333,
        type: chunk.type
      });
      if (meta && meta.decoderConfig && meta.decoderConfig.description) {
        this.videoDesc = new Uint8Array(meta.decoderConfig.description);
      }
    }

    addAudioChunk(chunk, meta) {
      const data = new Uint8Array(chunk.byteLength);
      chunk.copyTo(data);
      this.audioChunks.push({
        data,
        timestamp: chunk.timestamp,
        duration: chunk.duration || 23219
      });
      if (meta && meta.decoderConfig && meta.decoderConfig.description) {
        this.audioDesc = new Uint8Array(meta.decoderConfig.description);
      }
    }

    finalize() {
      const width = this.options.video.width;
      const height = this.options.video.height;
      const movieTimescale = 1000000;

      let videoDuration = 0;
      for (const c of this.videoChunks) videoDuration += c.duration;

      let audioDuration = 0;
      for (const c of this.audioChunks) audioDuration += c.duration;

      const totalDuration = Math.max(videoDuration, audioDuration);

      // 1. Сборка mdat
      let mdatSize = 8;
      for (const c of this.videoChunks) mdatSize += c.data.length;
      for (const c of this.audioChunks) mdatSize += c.data.length;

      const mdatHeader = new Uint8Array(8);
      new DataView(mdatHeader.buffer).setUint32(0, mdatSize);
      mdatHeader.set(new TextEncoder().encode('mdat'), 4);
      this.writer.write(mdatHeader);

      const videoOffsets = [];
      for (const c of this.videoChunks) {
        videoOffsets.push(this.writer.totalLength);
        this.writer.write(c.data);
      }

      const audioOffsets = [];
      for (const c of this.audioChunks) {
        audioOffsets.push(this.writer.totalLength);
        this.writer.write(c.data);
      }

      // 2. Сборка moov / mvhd
      const mvhd = new Uint8Array(108);
      const v = new DataView(mvhd.buffer);
      v.setUint32(0, 108);
      mvhd.set(new TextEncoder().encode('mvhd'), 4);
      v.setUint32(20, movieTimescale);
      v.setUint32(24, totalDuration);
      v.setUint32(28, 0x00010000);
      v.setUint16(32, 0x0100);
      v.setUint32(44, 0x00010000);
      v.setUint32(60, 0x00010000);
      v.setUint32(80, 0x40000000);
      v.setUint32(104, this.options.audio ? 3 : 2);

      // Видео дорожка (trak 1)
      const tkhdVideo = new Uint8Array(92);
      const tv = new DataView(tkhdVideo.buffer);
      tv.setUint32(0, 92);
      tkhdVideo.set(new TextEncoder().encode('tkhd'), 4);
      tv.setUint32(8, 0x00000003);
      tv.setUint32(12, 1);
      tv.setUint32(20, videoDuration);
      tv.setUint32(48, 0x00010000);
      tv.setUint32(64, 0x00010000);
      tv.setUint32(80, 0x40000000);
      tv.setUint32(84, width << 16);
      tv.setUint32(88, height << 16);

      const mdhdVideo = new Uint8Array(32);
      const mv = new DataView(mdhdVideo.buffer);
      mv.setUint32(0, 32);
      mdhdVideo.set(new TextEncoder().encode('mdhd'), 4);
      mv.setUint32(20, movieTimescale);
      mv.setUint32(24, videoDuration);

      const hdlrVideo = box('hdlr', new Uint8Array(4), new Uint8Array(4), 'vide', new Uint8Array(12), 'VideoHandler\0');
      const avcC = this.videoDesc ? box('avcC', this.videoDesc) : new Uint8Array(0);
      const avc1 = box('avc1', new Uint8Array(6), u16(1), new Uint8Array(16), u16(width), u16(height), u32(0x00480000), u32(0x00480000), new Uint8Array(4), u16(1), new Uint8Array(32), u16(0x0018), new Uint8Array([0xff, 0xff]), avcC);
      const stsdVideo = box('stsd', new Uint8Array(4), u32(1), avc1);

      const sttsVideoEntries = [];
      for (const c of this.videoChunks) sttsVideoEntries.push(u32(1), u32(c.duration));
      const sttsVideo = box('stts', new Uint8Array(4), u32(this.videoChunks.length), ...sttsVideoEntries);

      const keyFrames = [];
      this.videoChunks.forEach((c, idx) => { if (c.type === 'key') keyFrames.push(u32(idx + 1)); });
      const stssVideo = box('stss', new Uint8Array(4), u32(keyFrames.length), ...keyFrames);

      const stscVideo = box('stsc', new Uint8Array(4), u32(1), u32(1), u32(1), u32(1));
      const stszVideo = box('stsz', new Uint8Array(4), u32(0), u32(this.videoChunks.length), ...this.videoChunks.map(c => u32(c.data.length)));
      const stcoVideo = box('stco', new Uint8Array(4), u32(videoOffsets.length), ...videoOffsets.map(o => u32(o)));

      const stblVideo = box('stbl', stsdVideo, sttsVideo, stssVideo, stscVideo, stszVideo, stcoVideo);
      const vmhd = box('vmhd', new Uint8Array([0, 0, 0, 1]), new Uint8Array(8));
      const dinfVideo = box('dinf', box('dref', new Uint8Array(4), u32(1), box('url ', new Uint8Array([0, 0, 0, 1]))));
      const minfVideo = box('minf', vmhd, dinfVideo, stblVideo);
      const mdiaVideo = box('mdia', mdhdVideo, hdlrVideo, minfVideo);
      const trakVideo = box('trak', tkhdVideo, mdiaVideo);

      // Аудио дорожка (trak 2, если передано аудио)
      let trakAudio = new Uint8Array(0);
      if (this.options.audio && this.audioChunks.length > 0) {
        const audioRate = this.options.audio.sampleRate || 44100;
        const numChannels = this.options.audio.numberOfChannels || 2;

        const tkhdAudio = new Uint8Array(92);
        const ta = new DataView(tkhdAudio.buffer);
        ta.setUint32(0, 92);
        tkhdAudio.set(new TextEncoder().encode('tkhd'), 4);
        ta.setUint32(8, 0x00000003);
        ta.setUint32(12, 2);
        ta.setUint32(20, audioDuration);
        ta.setUint16(44, 0x0100); // sound volume
        ta.setUint32(48, 0x00010000);
        ta.setUint32(64, 0x00010000);
        ta.setUint32(80, 0x40000000);

        const mdhdAudio = new Uint8Array(32);
        const ma = new DataView(mdhdAudio.buffer);
        ma.setUint32(0, 32);
        mdhdAudio.set(new TextEncoder().encode('mdhd'), 4);
        ma.setUint32(20, movieTimescale);
        ma.setUint32(24, audioDuration);

        const hdlrAudio = box('hdlr', new Uint8Array(4), new Uint8Array(4), 'soun', new Uint8Array(12), 'SoundHandler\0');

        // esds box для AAC
        const esdsPayload = [
          0x03, 0x19, 0x00, 0x00, 0x00,
          0x04, 0x11, 0x40, 0x15, 0x00, 0x00, 0x00, 0x00, 0x01, 0xf4, 0x00, 0x00, 0x01, 0xf4, 0x00,
          0x05
        ];
        const descBytes = this.audioDesc || new Uint8Array([0x12, 0x10]);
        esdsPayload.push(descBytes.length);
        for (let i = 0; i < descBytes.length; i++) esdsPayload.push(descBytes[i]);
        esdsPayload.push(0x06, 0x01, 0x02);
        const esds = box('esds', new Uint8Array(4), new Uint8Array(esdsPayload));

        const mp4a = box('mp4a', new Uint8Array(6), u16(1), new Uint8Array(8), u16(numChannels), u16(16), new Uint8Array(4), u16(audioRate), new Uint8Array(2), esds);
        const stsdAudio = box('stsd', new Uint8Array(4), u32(1), mp4a);

        const sttsAudioEntries = [];
        for (const c of this.audioChunks) sttsAudioEntries.push(u32(1), u32(c.duration));
        const sttsAudio = box('stts', new Uint8Array(4), u32(this.audioChunks.length), ...sttsAudioEntries);
        const stscAudio = box('stsc', new Uint8Array(4), u32(1), u32(1), u32(1), u32(1));
        const stszAudio = box('stsz', new Uint8Array(4), u32(0), u32(this.audioChunks.length), ...this.audioChunks.map(c => u32(c.data.length)));
        const stcoAudio = box('stco', new Uint8Array(4), u32(audioOffsets.length), ...audioOffsets.map(o => u32(o)));

        const stblAudio = box('stbl', stsdAudio, sttsAudio, stscAudio, stszAudio, stcoAudio);
        const smhd = box('smhd', new Uint8Array(8));
        const dinfAudio = box('dinf', box('dref', new Uint8Array(4), u32(1), box('url ', new Uint8Array([0, 0, 0, 1]))));
        const minfAudio = box('minf', smhd, dinfAudio, stblAudio);
        const mdiaAudio = box('mdia', mdhdAudio, hdlrAudio, minfAudio);
        trakAudio = box('trak', tkhdAudio, mdiaAudio);
      }

      const moov = box('moov', mvhd, trakVideo, trakAudio);
      this.writer.write(moov);
      this.target.buffer = this.writer.finalize();
    }
  }

  exports.ArrayBufferTarget = ArrayBufferTarget;
  exports.Muxer = Muxer;
}));